import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axiosInstance from '../axiosConfig';

// REQ-1.1: Public Homepage — accessible without authentication.
// REQ-1.2: Tournament Search — search by sport name or tournament name.
// REQ-1.3: Tournament Display
const Home = () => {
  const [tournaments, setTournaments] = useState([]);
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(true);
  const [searching, setSearching] = useState(false);

  const fetchTournaments = async (searchQuery = '') => {
    setLoading(true);
    try {
      const endpoint = searchQuery
        ? `/api/tournaments/search?q=${encodeURIComponent(searchQuery)}`
        : '/api/tournaments';
      const response = await axiosInstance.get(endpoint);
      setTournaments(response.data);
    } catch (error) {
      alert('Failed to load tournaments.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTournaments();
  }, []);


  const handleSearch = (e) => {
    e.preventDefault();
    setSearching(query.trim().length > 0);
    fetchTournaments(query);
  };

  const renderGrid = (list) => (
    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
      {list.map((t) => (
        <Link
          to={`/tournaments/${t._id}`}
          key={t._id}
          className="bg-gray-100 p-4 rounded shadow hover:shadow-md transition"
        >
          <h2 className="font-bold text-lg">{t.name}</h2>
          <p className="text-sm text-gray-600">{t.sport}</p>
          <p className="text-sm text-gray-500">
            {new Date(t.date).toLocaleDateString()}
          </p>
          <p className="text-sm mt-1">
            {t.participants.length}/{t.maxCapacity} joined &middot; {t.status}
          </p>
        </Link>
      ))}
    </div>
  );

  const now = new Date();
  // STS-03: Upcoming — tournaments scheduled for today or later
  const upcoming = tournaments.filter((t) => new Date(t.date) >= now);
  // STS-02: Recent — tournaments already held, most recent first
  const recent = [...tournaments]
    .filter((t) => new Date(t.date) < now)
    .sort((a, b) => new Date(b.date) - new Date(a.date));

  return (
    <div className="container mx-auto p-6">
      <h1 className="text-3xl font-bold mb-6">Discover Tournaments</h1>

      <form onSubmit={handleSearch} className="mb-6 flex">
        <input
          type="text"
          placeholder="Search by tournament or sport name"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          className="flex-1 p-2 border rounded-l"
        />
        <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded-r">
          Search
        </button>
      </form>

      {loading ? (
        <p>Loading...</p>
      ) : tournaments.length === 0 ? (
        <p className="text-gray-500">No tournaments found.</p>
      ) : searching ? (
        renderGrid(tournaments)
      ) : (
        <>
          <h2 className="text-xl font-semibold mb-3">Upcoming Tournaments</h2>
          {upcoming.length === 0 ? (
            <p className="text-gray-500 mb-8">No upcoming tournaments right now.</p>
          ) : (
            <div className="mb-8">{renderGrid(upcoming)}</div>
          )}

          <h2 className="text-xl font-semibold mb-3">Recent Tournaments</h2>
          {recent.length === 0 ? (
            <p className="text-gray-500">No past tournaments yet.</p>
          ) : (
            renderGrid(recent.slice(0, 6))
          )}
        </>
      )}
    </div>
  );
};

export default Home;
